// renovateHints index RenovateOptions for unknown-key hints: the first row of each key with
// a To or a Note.
var renovateHints = func() map[string]*RenovateOption {
	m := map[string]*RenovateOption{}
	for i := range RenovateOptions {
		o := &RenovateOptions[i]
		if o.To == "" && o.Note == "" {
			continue
		}
		for _, k := range o.Keys {
			if _, ok := m[k]; !ok {
				m[k] = o
			}
		}
	}
	return m
}()

// Columns returns the Renovate and deps columns of the row in markdown.
func (o RenovateOption) Columns() (renovate, deps string) {
	renovate = o.Renovate
	switch {
	case renovate != "":
	case o.From != "":
		renovate = "`" + o.From + "`"
	default:
		renovate = "`" + strings.Join(o.Keys, "`, `") + "`"
	}
	if o.To != "" {
		deps = "`" + o.scopedTo() + "`"
	}
	return renovate, deps + o.Doc
}

// scopedTo returns To prefixed with its Scope.
func (o RenovateOption) scopedTo() string {
	if o.Scope == "" {
		return o.To
	}
	return o.Scope + "." + o.To
}

// ValidCustomDatasourceName reports whether name is an accepted customDatasources key
// (CustomDatasourceNamePattern).
func ValidCustomDatasourceName(name string) bool { return customDatasourceNameRe.MatchString(name) }
